    const fs = perf.stats(); ftimeEl.textContent = `${fs.avg.toFixed(1)} · p95 ${fs.p95.toFixed(0)} · max ${fs.max.toFixed(0)}`;
    showEl.textContent = showLabel(); frames = 0; fpsT = 0;
