  // upload hình học lên GPU, biên dịch biến thể vẽ bóng (MeshDepthMaterial) và phần trình điều khiển biên dịch lười lúc vẽ lần đầu
  // (đo GĐ1: không còn program mới nhưng lần đầu bay tới Thuận Phước / Hầm / Vòng quay vẫn khựng 3–5 s trên SwiftShader). Trả nguyên trạng ngay sau đó.
  const saved: [THREE.Object3D, boolean, boolean][] = [], counts: [THREE.InstancedMesh, number][] = [], lods: THREE.LOD[] = [];
  scene.traverse((o) => {
    saved.push([o, o.visible, o.frustumCulled]); o.visible = true; o.frustumCulled = false;
    const im = o as THREE.InstancedMesh; if (im.isInstancedMesh && im.count === 0) { counts.push([im, 0]); im.count = 1; }
    const lod = o as THREE.LOD; if (lod.isLOD && lod.autoUpdate) { lods.push(lod); lod.autoUpdate = false; }
  });
  renderer.render(scene, camera);
  composer.render(0);
  for (const [o, v, f] of saved) { o.visible = v; o.frustumCulled = f; }
  for (const [im, n] of counts) im.count = n;
  for (const lod of lods) lod.autoUpdate = true;
  composer.render(0);   // một lần nữa với trạng thái thật (bloom/output pass đã biên dịch ở lần trên)
}
/* =====================================================================
   THIẾT BỊ (D-018) — đoán một lần lúc tải, trước khi tạo renderer: có phải điện thoại / máy yếu không.
   Dùng cho những thứ chỉ đặt được lúc khởi động (antialias của WebGL context, bóng đổ có tính trong shader không)
   và bậc khởi đầu của chế độ chất lượng Tự động. ?test luôn coi là máy tính mạnh để bảng draw call chuẩn giữ nguyên.
   ===================================================================== */
const q = new URLSearchParams(location.search);
const nav = navigator as Navigator & { deviceMemory?: number };
const coarse = typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches;
const small = Math.min(screen.width, screen.height) < 900;

export const device = {
  test: q.has('test'),
  phone: !q.has('test') && coarse && small,                                                     // màn cảm ứng nhỏ: điện thoại / máy tính bảng nhỏ
  weak: !q.has('test') && ((nav.deviceMemory ?? 8) <= 4 || (navigator.hardwareConcurrency ?? 8) <= 4)
};
import * as THREE from 'three';
import { scene, renderer } from './renderer';
import { shared } from './shared';
import { MAT } from './materials';
import { sun, hemi, moon, bridgeLights } from './lights';
import { setSun, stars, clouds } from './sky';
import { water } from './water';
import { lerp, clamp } from '../common/math';

/* ============================ Ngày / đêm ============================ */
/* night: giá trị hiện tại (0 ngày → 1 đêm), target: giá trị người xem chọn; night tiến dần về target */
export const dayNight = { night: 0, target: 0 };

const C_FOG_DAY = new THREE.Color(0xcfdde6), C_FOG_NIGHT = new THREE.Color(0x0b1424);
const C_HEMI_DAY = new THREE.Color(0xcfe6ff), C_HEMI_NIGHT = new THREE.Color(0x2a3a66);
const C_WATER_DAY = new THREE.Color(0x2c5a4f), C_WATER_NIGHT = new THREE.Color(0x08181b);
const C_BULB_DAY = new THREE.Color(0x9a9890), C_BULB_NIGHT = new THREE.Color(2.4, 1.9, 1.1);

export function applyNight(m: number, time: number) {
  shared.uNight.value = m;
  setSun(lerp(40, -7, m), 205);
  sun.intensity = 3.0 * clamp(1 - m * 1.15, 0, 1);
  moon.intensity = 0.35 * m;
  hemi.intensity = lerp(0.9, 0.22, m);
  hemi.color.copy(C_HEMI_DAY).lerp(C_HEMI_NIGHT, m);
  (scene.fog as THREE.FogExp2).color.copy(C_FOG_DAY).lerp(C_FOG_NIGHT, m);
  scene.environmentIntensity = lerp(1, 0.14, m);
  renderer.toneMappingExposure = lerp(0.55, 0.8, m);
  water.material.uniforms.waterColor.value.copy(C_WATER_DAY).lerp(C_WATER_NIGHT, m);
  water.material.uniforms.sunColor.value.setRGB(lerp(1, 0.25, m), lerp(1, 0.3, m), lerp(1, 0.45, m));
  stars.material.opacity = clamp((m - 0.4) / 0.6, 0, 1);
  clouds.material.opacity = lerp(0.85, 0.12, m);
  MAT.bulb.color.copy(C_BULB_DAY).lerp(C_BULB_NIGHT, m);
  MAT.pupil.emissiveIntensity = m * 2.5;
  MAT.eye.emissiveIntensity = 0.05 + m * 0.4;
  // Đèn dọc cầu nhấp nháy nhẹ theo sin(time)
  bridgeLights.forEach((l) => { l.intensity = l.userData.base * m * (0.82 + 0.18 * Math.sin(time * 2.2 + l.userData.phase)); });
}
/* Một bước chuyển ngày ↔ đêm mỗi khung hình */
export function stepNight(dt: number) {
  dayNight.night += (dayNight.target - dayNight.night) * Math.min(1, dt * 1.6);
  if (Math.abs(dayNight.target - dayNight.night) < 0.001) dayNight.night = dayNight.target;
}
// Tiện ích chung cho các script kiểm tra: server tĩnh + mở trang bằng Chromium (Playwright).
import { fileURLToPath } from 'node:url';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'playwright';

const THREE_DIR = fileURLToPath(new URL('../node_modules/three/', import.meta.url));
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.mp3': 'audio/mpeg', '.png': 'image/png' };

/** Server tĩnh tối giản cho một thư mục (theo symlink). Trả về { url, close }. */
export function serveDir(dir) {
  const root = path.resolve(dir);
  const server = http.createServer((req, res) => {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p.endsWith('/')) p += 'index.html';
    let file = path.join(root, p);
    if (!file.startsWith(root)) { res.writeHead(403); return res.end(); }
    // Bản gốc nạp three từ /three/… : nếu thư mục không có thì lấy từ node_modules/three của project
    if (p.startsWith('/three/') && !fs.existsSync(file)) file = path.join(THREE_DIR, p.slice('/three/'.length));
    fs.readFile(file, (err, data) => {
      if (err) { res.writeHead(404); return res.end('not found'); }
      res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
      res.end(data);
    });
  });
  return new Promise((ok) => server.listen(0, '127.0.0.1', () => ok({ url: `http://127.0.0.1:${server.address().port}/`, close: () => server.close() })));
}

export async function launch() {
  return chromium.launch({
    executablePath: process.env.CHROMIUM_PATH || undefined,
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
  });
}

/** Mở trang với ?test, chặn font Google (không cần cho kiểm tra), chờ khung hình đầu. */
export async function openApp(browser, url, { width = 480, height = 270, mobile = false } = {}) {
  const page = await browser.newPage(mobile ? { viewport: { width, height }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : { viewport: { width, height } });
  const errors = []; page.setDefaultTimeout(240000);
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errors.push(m.text()); });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
  await page.goto(url + (url.includes('?') ? '&' : '?') + 'test', { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  return { page, errors };
}

/** Chờ n khung hình. */
export const frames = (page, n = 2) => page.evaluate((n) => new Promise((ok) => { let i = 0; const f = () => (++i >= n ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }), n);

/** Chờ hiệu ứng bay camera (flyTo) kết thúc. */
// Phần mềm dựng hình (SwiftShader) rất chậm nên tua nhanh: đẩy tiến độ bay gần tới đích để khung hình kế tiếp hoàn tất.
export async function waitFlight(page) {
  await page.evaluate(() => { const f = window.__app.cam.flight; if (window.__app.cam.mode === 'fly') f.t = Math.max(f.t, 0.999); });
  await page.waitForFunction(() => window.__app.cam.mode !== 'fly', null, { timeout: 240000 });
}

/** Bấm một phần tử: ở chế độ gọn thì mở đúng tờ chứa nó trước (reveal), chờ 1 khung, rồi bấm. */
export async function tap(page, sel) {
  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
  await frames(page, 1);
  await page.click(sel);
}

/** Như tap nhưng cho ô chọn (select). */
export async function pick(page, sel, value) {
  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
  await frames(page, 1);
  await page.selectOption(sel, value);
}

/** Chọn cầu rồi bấm nút góc nhìn. */
export async function pickView(page, bridge, view) {
  await tap(page, `button[data-bridge="${bridge}"]`);
  await waitFlight(page);
  await tap(page, `button[data-view="${view}"]`);
  await waitFlight(page);
}

