// Đo thời gian vẽ trên GPU thật (không phải SwiftShader): tách lượt bóng / phản chiếu / chính, và chi phí từng lưới nặng.
// node profile.mjs <repo> [--sw] [--w=1920 --h=1080] [--night]
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const repo = process.argv[2];
const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
const W = +arg('w', 1920), H = +arg('h', 1080), sw = process.argv.includes('--sw'), night = process.argv.includes('--night');
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);

const srv = await lib.serveDir(path.join(repo, 'dist'));
const browser = await chromium.launch({
  headless: true,
  args: sw ? ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
    : ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit']
});
const { page, errors } = await lib.openApp(browser, srv.url + '?perf', { width: W, height: H });
try {
  const info = await page.evaluate(() => {
    const gl = window.__app.renderer.getContext(), e = gl.getExtension('WEBGL_debug_renderer_info');
    return { gpu: e ? gl.getParameter(e.UNMASKED_RENDERER_WEBGL) : '?', ratio: window.__app.renderer.getPixelRatio(), dpr: devicePixelRatio };
  });
  console.log('GPU:', info.gpu, '| pixelRatio', info.ratio, '| khung', W, 'x', H, night ? '| ĐÊM' : '| ngày');
  if (night) { await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 1; }); await lib.frames(page, 5); }

  // Thời gian khung thật của vòng animate (rAF, không vsync) + CPU từng bước
  const loop = async (label) => {
    await lib.frames(page, 20);
    const r = await page.evaluate(() => new Promise((ok) => {
      const P = window.__app.perf; P.reset(); const t0 = performance.now(); let n = 0;
      const f = () => { if (++n >= 120) { const o = {}; for (const [k, v] of Object.entries(P.sums)) o[k] = +(v / P.frames).toFixed(2); ok({ frame: +((performance.now() - t0) / n).toFixed(2), max: +P.maxFrame.toFixed(1), laps: o, calls: window.__app.renderer.info.render.calls, tris: window.__app.renderer.info.render.triangles }); } else requestAnimationFrame(f); };
      requestAnimationFrame(f);
    }));
    console.log(`[vòng animate] ${label}: ${r.frame} ms/khung (max ${r.max}), ${r.calls} lệnh vẽ, ${r.tris} tam giác`);
    console.log('   ', JSON.stringify(r.laps));
  };
  await loop('mặc định');

  // Đo đồng bộ: vẽ n lần + readPixels (ép GPU xong việc)
  const res = await page.evaluate((night) => {
    const A = window.__app, R = A.renderer, gl = R.getContext(), px = new Uint8Array(4);
    const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
    const t = (n = 30) => {
      draw(); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      const t0 = performance.now();
      for (let i = 0; i < n; i++) draw();
      gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      return { ms: +((performance.now() - t0) / n).toFixed(2), calls: R.info.render.calls, tris: R.info.render.triangles };
    };
    const out = {};
    out.full = t();
    R.shadowMap.autoUpdate = false; out.noShadow = t();
    A.reflectState.every = 0; out.noShadowNoReflect = t();
    R.shadowMap.autoUpdate = true; out.noReflect = t();
    A.reflectState.every = 1;
    // Lưới nặng nhất: tam giác × instance
    const list = [];
    A.scene.traverse((o) => {
      if (!o.isMesh || !o.geometry) return;
      let vis = true; for (let p = o; p; p = p.parent) if (!p.visible) vis = false;
      const g = o.geometry, tri = (g.index ? g.index.count : g.attributes.position?.count || 0) / 3, n = o.isInstancedMesh ? o.count : 1;
      list.push({ o, name: o.name || o.parent?.name || o.type, tris: Math.round(tri * n), inst: n, shadow: o.castShadow, layer1: o.layers.mask === 2, vis, culled: o.frustumCulled });
    });
    list.sort((a, b) => b.tris - a.tris);
    out.total = list.reduce((s, x) => s + (x.vis ? x.tris : 0), 0);
    out.meshes = list.length;
    out.top = [];
    const base = t(40).ms;
    out.base2 = base;
    for (const x of list.filter((x) => x.vis).slice(0, 28)) {
      x.o.visible = false; const r = t(20); x.o.visible = true;
      out.top.push({ name: x.name, tris: x.tris, inst: x.inst, shadow: x.shadow, layer1: x.layer1, culled: x.culled, saveMs: +(base - r.ms).toFixed(2), saveCalls: out.full.calls - r.calls });
    }
    out.base3 = t(40).ms;
    return out;
  }, night);
  const { top, ...sum } = res;
  console.log(JSON.stringify(sum, null, 1));
  console.table(top);
  if (errors.length) console.log('LỖI console:', errors);
} finally { await browser.close(); srv.close(); }

// A/B xen kẽ trên GPU thật: mỗi cấu hình đo nhiều vòng, lấy trung vị. node ab.mjs <repo> [--w= --h=] [--night] [--view=bridge,view]
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const repo = process.argv[2];
const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
