  if (night) { await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 1; }); }
  await lib.frames(page, 10);
  const res = await page.evaluate(async (night) => {
    const A = window.__app, R = A.renderer, gl = R.getContext(), px = new Uint8Array(4);
    const byName = (n) => { const l = []; A.scene.traverse((o) => { if (o.name === n && o.isMesh) l.push(o); }); return l; };
    const composer = null;
    const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
    const t = (n = 20) => {
      draw(); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      const t0 = performance.now();
      for (let i = 0; i < n; i++) { draw(); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); }
      return (performance.now() - t0) / n;
    };
    // lưới ẩn riêng trong lượt phản chiếu: bọc onBeforeRender của nước
    const water = A.scene.children.find((o) => o.material?.uniforms?.mirrorSampler);
    const wDraw = water.onBeforeRender; let hideInMirror = [];
    water.onBeforeRender = function (...a) { for (const o of hideInMirror) o.visible = false; wDraw.apply(this, a); for (const o of hideInMirror) o.visible = true; };
    const crown = byName('trees-shade-crown'), trunk = byName('trees-shade-trunk'), palmC = byName('trees-palm-crown'), palmT = byName('trees-palm-trunk'), cars = byName('traffic-city'), boats = byName('boats-river');
    const trees = [...crown, ...trunk, ...palmC, ...palmT];
